# Modify this to change how the CLI connects to the MCP server.
CLIENT_SPEC = StdioTransport(command=sys.executable, args=['-m', 'astrophotoflow.interfaces.mcp.server'], env={**({'ASTROPHOTOFLOW_CONFIG': os.environ['ASTROPHOTOFLOW_CONFIG']} if 'ASTROPHOTOFLOW_CONFIG' in os.environ else {}), 'PYTHONUTF8': '1'})

